/usr/bin/bash -lc "python -B - <<'PY'
import math, statistics, json, cmath
Phi=statistics.NormalDist().cdf
gamma=statistics.NormalDist().inv_cdf(.999)
rho=16*26/101
rho_req=(gamma+statistics.NormalDist().inv_cdf(.9))**2/2
w=(1,-25*math.sqrt(3)/26)
var=w[0]**2*76+2*w[0]*w[1]*25*math.sqrt(3)+w[1]**2*26
out={'gamma':gamma,'q0':26/101,'w':w,'output_variance_over_sigma2':var,'rho':rho,'mean_Z':math.sqrt(2*rho),'PD_colored':Phi(math.sqrt(2*rho)-gamma),'PD_first':Phi(math.sqrt(32/76)-gamma),'PD_null':Phi(math.sqrt(8)-gamma),'rho_required':rho_req,'A2_over_sigma2_required':rho_req*101/26,'A_mV_required':math.sqrt(rho_req*101/26),'PD_four_independent':Phi(math.sqrt(8*rho)-gamma),'PD_theta_zero':Phi(math.sqrt(32/101)-gamma)}
def tail_gamma(shape,x):
    return math.exp(-x)*sum(x**k/math.factorial(k) for k in range(shape))
def nc_tail(shape,lam,x):
    p=math.exp(-lam); s=0
    for k in range(200):
        s+=p*tail_gamma(shape+k,x)
        p*=lam/(k+1)
    return s
lo,hi=0.,50.
for _ in range(100):
    mid=(lo+hi)/2
    if tail_gamma(4,mid)>.001:lo=mid
    else:hi=mid
eta4=(lo+hi)/2
out.update({'unknown_phase_threshold':-math.log(.001),'PD_unknown_single':nc_tail(1,rho,-math.log(.001)),'eta_noncoherent_four':eta4,'PD_noncoherent_four':nc_tail(4,4*rho,eta4)})
out['L4_spots']={str(d):abs(sum(cmath.exp(1j*m*math.radians(d)) for m in range(4))/4)**2 for d in [0,45,60,90,120,135,180]}
out['q0_curves']={str(d):{'opt':math.sin(math.radians(d))**2+math.cos(math.radians(d))**2/101,'hard_null':math.sin(math.radians(d))**2,'first':1/(1+100*math.cos(math.radians(d))**2)} for d in [0,30,45,90]}
h=100/101; noise=100*(1-h)**2+1+h*h
out['leakage']={'h':h,'noise':noise,'noise_reduction_db':10*math.log10(101/noise),'wanted_loss_db':-20*math.log10(1-h),'snr_change_db':10*math.log10((1-h)**2*101/noise),'transfer_db_spots':{str(l):20*math.log10(abs(1-h*l)) for l in [0,.25,.5,.75,1]}}
out['correlation']={'complex_rms':math.sqrt(1.01**2/10000),'real_sd':math.sqrt((1.01**2+.01**2)/20000),'imag_sd':math.sqrt((1.01**2-.01**2)/20000)}
# Shared interferer, four equal phases: stacked covariance I+100 vv"'^H, ||v||''^2=4.
# qstack = ||a_stack||''^2 - 100 |v''^H a_stack|''^2 /401.
qstack=4-100*(4*math.cos(math.pi/6))**2/401
out['"'shared_interferer']={'q0_stacked':qstack,'rho_stacked':16*qstack,'PD':Phi(math.sqrt(32*qstack)-gamma),'equivalent_noise_variance_for_mean':1/qstack,'unit_response_weights_per_record':[1/4,-100*math.cos(math.pi/6)*math.sin(math.pi/6)/(1+400*math.sin(math.pi/6)**2)]}
print(json.dumps(out,indent=2))
PY"

