from html.parser import HTMLParser
from pathlib import Path
class Page(HTMLParser):
 def __init__(self):super().__init__();self.ids=set();self.links=[];self.imgs=[]
 def handle_starttag(self,t,attrs):
  a=dict(attrs)
  if 'id' in a:self.ids.add(a['id'])
  if t=='a':self.links.append(a.get('href',''))
  if t=='img':self.imgs.append(a)
p=Page();p.feed(Path('rendered/extraction-integration-rejection.html').read_text())
print('Missing internal fragment targets:', sorted(set(h for h in p.links if h.startswith('#') and h[1:] not in p.ids)))
